package dao; import dto.CommentDTO; import util.DBConnection; import java.sql.*; import java.util.*;
public class CommentDAO { public int insert(CommentDTO x)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO comment(post_id,member_id,content) VALUES(?,?,?)")){p.setLong(1,x.getPostId());p.setLong(2,x.getMemberId());p.setString(3,x.getContent());return p.executeUpdate();}}
public int delete(long id,long memberId,boolean admin)throws Exception{String s=admin?"DELETE FROM comment WHERE comment_id=?":"DELETE FROM comment WHERE comment_id=? AND member_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setLong(1,id);if(!admin)p.setLong(2,memberId);return p.executeUpdate();}}
public CommentDTO selectById(long id)throws Exception{String s="SELECT c.*,m.nickname member_nickname FROM comment c JOIN member m ON c.member_id=m.member_id WHERE c.comment_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
public List<CommentDTO> selectByPostId(long id)throws Exception{List<CommentDTO>a=new ArrayList<>();String s="SELECT c.*,m.nickname member_nickname FROM comment c JOIN member m ON c.member_id=m.member_id WHERE c.post_id=? ORDER BY c.created_at ASC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}return a;}
private CommentDTO map(ResultSet r)throws SQLException{CommentDTO x=new CommentDTO();x.setCommentId(r.getLong("comment_id"));x.setPostId(r.getLong("post_id"));x.setMemberId(r.getLong("member_id"));x.setContent(r.getString("content"));x.setLikeCount(r.getInt("like_count"));x.setDislikeCount(r.getInt("dislike_count"));x.setCreatedAt(r.getTimestamp("created_at"));x.setUpdatedAt(r.getTimestamp("updated_at"));x.setMemberNickname(r.getString("member_nickname"));return x;}}
